<?php $title="Add Bicycle";require "includes/header.php";if($_SERVER["REQUEST_METHOD"]==="POST"){$s=$conn->prepare("INSERT INTO bicycles(name,sku,category,price,stock,ai_tag) VALUES(?,?,?,?,?,?)");$p=(float)$_POST["price"];$q=(int)$_POST["stock"];$s->bind_param("sssdis",$_POST["name"],$_POST["sku"],$_POST["category"],$p,$q,$_POST["ai_tag"]);$s->execute();go("bicycles.php");}?><div class="card"><h2>Add Bicycle</h2><form method="post"><label>Model</label><input name="name" required><label>SKU</label><input name="sku" required><label>Category</label><select name="category"><option>Mountain</option><option>Road</option><option>City</option><option>Electric</option><option>Kids</option></select><label>Price</label><input name="price" type="number" step=".01" required><label>Stock</label><input name="stock" type="number" required><label>AI Tag</label><input name="ai_tag" placeholder="Adventure / Premium"><button class="btn primary">Save</button></form></div><?php require "includes/footer.php";?>